def isprogram_df():
    return pd.DataFrame(ISPROGRAM)


def progress_rows():
    """122 hakediş kalemini ana ilerleme şemasına çevirir. grp = grup (PV/Kablo/İnşaat...)."""
    out = []
    for it in ISPROGRAM:
        out.append({
            'id': it['poz'], 'grp': it['grup'], 'disc': it['grup'],
            'name': it['ad'], 'unit': it['birim'],
            'qty': float(it['miktar']), 'up': float(it['bf']),
            'plan': 0.0, 'real': 0.0,
        })
    return out
